The `wit/world.wit` and `src/lib.rs` are below. I left out the `http-client` enrichment fetch, because part of my earlier response was withheld and I can't tell which part, so I kept the node to the `notifier` authority it was originally granted. The node notifies the channel and reports whether the notification was accepted, so `published` is always set.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let kept = composed.entries.iter().filter(|e| e.kept).count();
        let message = format!(
            "Digest {}: {} ({} entries, {} kept, {} considered)",
            composed.date,
            composed.overview,
            composed.entries.len(),
            kept,
            composed.considered.len()
        );
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

